import React from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type FastForwardAnimationProps = Record<string, any>;

const FastForwardSvg: React.FC<{ color: string }> = ({ color }) => (
  <svg
    width="100%"
    height="100%"
    viewBox="0 0 200 100"
    style={{ overflow: "visible", transition: "none" }}
  >
    <polygon points="0,0 90,50 0,100" fill={color} style={{ transition: "none" }} />
    <polygon points="100,0 190,50 100,100" fill={color} style={{ transition: "none" }} />
  </svg>
);

const FastForwardAnimation: React.FC<FastForwardAnimationProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 3,
  iconColor = "#ffffff",
  iconSize = 300,
  trailIntensity = 0.5,
}) => {
  {/* Load Google Fonts as required by structure, even for icon-only designs */}
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // Parser safety for background transparency
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Timeline Configurations
  const totalFrames = durationInSeconds * fps;
  const introDuration = 15;
  const outroDuration = 20;
  const outroStart = totalFrames - outroDuration;

  // Global Scale Intro
  const scaleIn = spring({
    frame,
    fps,
    config: { damping: 12, mass: 0.6, stiffness: 120 },
  });

  // Core motion calculator function for accurate trailing
  const calculateMotionParams = (f: number) => {
    const clampedF = Math.max(0, f);
    
    // Middle phase: building up speed/tension
    const midProgress = interpolate(clampedF, [introDuration, outroStart], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.in(Easing.quad),
    });

    // Slight shift to the right before the big exit
    const midShift = midProgress * (width * 0.15);
    
    // Exit phase: rapid acceleration off-screen to the right
    const exitDist = interpolate(clampedF, [outroStart, outroStart + 15], [0, width * 1.5], {
      easing: Easing.in(Easing.poly(4)),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });

    const xPos = midShift + exitDist;

    // Skewing creates a visual sense of speed (leaning forward)
    const skewMid = interpolate(midProgress, [0, 1], [0, -15]);
    const skewExit = interpolate(clampedF, [outroStart, outroStart + 15], [0, -35], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.in(Easing.ease),
    });

    const skew = skewMid + skewExit;

    return { xPos, skew, midProgress };
  };

  const mainMotion = calculateMotionParams(frame);

  // Dynamic rhythmic pulse during the middle sequence to simulate acceleration
  const pulseAmplitude = interpolate(mainMotion.midProgress, [0, 1], [0, 0.06]);
  const pulseScale = frame > introDuration && frame < outroStart
    ? 1 - Math.abs(Math.sin(frame * 0.4)) * pulseAmplitude
    : 1;

  const mainScale = scaleIn * pulseScale;

  // Directional Blur (Streaked look pushing to the right)
  const blurBase = interpolate(mainMotion.midProgress, [0, 1], [0, 12]);
  const blurExit = interpolate(frame, [outroStart, outroStart + 10], [0, 80], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.in(Easing.exp),
  });
  const currentBlurX = blurBase + blurExit;

  // Motion Trails Generator
  const trailCount = 5;
  const trailElements = Array.from({ length: trailCount }).map((_, i) => {
    const delay = (i + 1) * 2;
    const trailFrame = frame - delay;
    
    if (trailFrame < 0) return null;

    const motion = calculateMotionParams(trailFrame);
    
    // Trails fade out naturally based on intensity config and distance
    const baseOpacity = interpolate(motion.midProgress, [0, 1], [0, trailIntensity]) * (1 - i / trailCount);
    
    // Trails cleanly dissolve during the final exit so they don't awkwardly linger
    const exitFade = interpolate(trailFrame, [outroStart, outroStart + 10], [1, 0], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });

    return {
      id: `trail-${i}`,
      x: motion.xPos,
      skew: motion.skew,
      opacity: baseOpacity * exitFade,
      scale: scaleIn, // Keeps trail size consistent with intro pop
    };
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter",
        justifyContent: "center",
        alignItems: "center",
        transition: "none",
      }}
    >
      {/* SVG Defs for Streaked Directional Blur */}
      <svg width="0" height="0" style={{ position: "absolute", transition: "none" }}>
        <defs>
          {/* Extended bounds prevent the blur from clipping at the edges of the SVG box */}
          <filter id="directionalBlur" x="-100%" y="-100%" width="300%" height="300%">
            <feGaussianBlur in="SourceGraphic" stdDeviation={`${currentBlurX}, 0`} />
          </filter>
        </defs>
      </svg>

      {/* Main Container */}
      <div
        style={{
          position: "relative",
          width: iconSize,
          height: iconSize * 0.5,
          transition: "none",
        }}
      >
        {/* Render Trails (Rendered first so they sit behind the main icon) */}
        {trailElements.map(
          (trail) =>
            trail && (
              <div
                key={trail.id}
                style={{
                  position: "absolute",
                  top: 0,
                  left: 0,
                  width: "100%",
                  height: "100%",
                  opacity: trail.opacity,
                  transform: `translateX(${trail.x}px) scale(${trail.scale}) skewX(${trail.skew}deg)`,
                  transformOrigin: "center center",
                  filter: "url(#directionalBlur)",
                  transition: "none",
                }}
              >
                <FastForwardSvg color={iconColor} />
              </div>
            )
        )}

        {/* Render Main Icon */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            transform: `translateX(${mainMotion.xPos}px) scale(${mainScale}) skewX(${mainMotion.skew}deg)`,
            transformOrigin: "center center",
            filter: "url(#directionalBlur)",
            transition: "none",
            opacity: scaleIn > 0.05 ? 1 : 0, 
          }}
        >
          <FastForwardSvg color={iconColor} />
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default FastForwardAnimation;